# ptx-fresh.ps1 -- is every generated PTX chapter what its [Device] source emits today?
#
#   pwsh build/checks/ptx-fresh.ps1                  # every chapter, plug rebuilt from head first
#   pwsh build/checks/ptx-fresh.ps1 -Only GemmPtx    # one chapter, by file stem
#   pwsh build/checks/ptx-fresh.ps1 -NoBuild         # use the plug CDX as it stands
#
# The codex/test/gpu-* tests launch the generated chapter, not the source, and the
# coverage census credits the source through the "Generated by ... from X.codex"
# header, so both are true only while the chapter is regenerated after every source
# or plug change. On demand, never a gate: it boots one plug guest per chapter,
# serially. Exit 0 every chapter fresh, 1 at least one stale, 2 could not run.
[CmdletBinding()]
param(
    [string]$Only = '',
    [switch]$NoBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$Root = (Resolve-Path (Join-Path $PSScriptRoot '..' '..')).Path
$RunPs1 = Join-Path $Root 'codex/plugs/ptx/run.ps1'
$Work = Join-Path ([System.IO.Path]::GetTempPath()) ("ptx-fresh-{0}-{1}" -f $PID, (Get-Date -Format 'HHmmssfff'))

$chapters = @()
foreach ($f in Get-ChildItem (Join-Path $Root 'codex'), (Join-Path $Root 'apps') -Recurse -Filter *.codex | Where-Object { $_.FullName -notmatch '[\\/]build-output[\\/]' }) {
    $hit = Select-String -Path $f.FullName -Pattern '^ Generated by codex/plugs/ptx/run\.ps1 -Chapter from ([A-Za-z0-9]+\.codex)' | Select-Object -First 1
    if (-not $hit) { continue }
    if ($Only -and $f.BaseName -ne $Only) { continue }
    $def = Select-String -Path $f.FullName -Pattern '^  ([a-z0-9-]+) : Text\s*$' | Select-Object -First 1
    $chapter = (Get-Content $f.FullName -TotalCount 1) -replace '^Chapter:\s*', ''
    $chapters += [pscustomobject]@{ File = $f.FullName; Src = Join-Path $f.DirectoryName $hit.Matches[0].Groups[1].Value; Chapter = $chapter.Trim(); Name = $(if ($def) { $def.Matches[0].Groups[1].Value } else { '' }) }
}
if ($chapters.Count -eq 0) { Write-Host "FAIL: no generated PTX chapter$(if ($Only) { " named $Only" })"; exit 2 }

if (-not $NoBuild) {
    & pwsh -NoProfile -File (Join-Path $Root 'codex/plugs/ptx/build.ps1') | Out-Null
    if ($LASTEXITCODE -ne 0) { Write-Host 'FAIL: the PTX plug did not build'; exit 2 }
}
New-Item -ItemType Directory -Force -Path $Work | Out-Null

$stale = 0; $broken = 0
foreach ($c in $chapters) {
    $rel = $c.File.Substring($Root.Length + 1) -replace '\\', '/'
    if (-not $c.Name -or -not (Test-Path $c.Src)) { Write-Host "  BROKEN  $rel  (no Text definition, or source $($c.Src) missing)"; $broken++; continue }
    $out = Join-Path $Work ([System.IO.Path]::GetFileName($c.File))
    & pwsh -NoProfile -File $RunPs1 -Src $c.Src -Out $out -Chapter $c.Chapter -Name $c.Name *> (Join-Path $Work "$([System.IO.Path]::GetFileNameWithoutExtension($c.File)).log")
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path $out)) { Write-Host "  BROKEN  $rel  (run.ps1 exit $LASTEXITCODE; log in $Work)"; $broken++; continue }
    $pat = '^  ' + [regex]::Escape($c.Name) + ' = "'
    $have = @(Get-Content $c.File | Where-Object { $_ -match $pat })
    $made = @(Get-Content $out | Where-Object { $_ -match $pat })
    if ($have.Count -ne 1 -or $made.Count -ne 1) { Write-Host "  BROKEN  $rel  (literal lines: depot $($have.Count), regenerated $($made.Count))"; $broken++; continue }
    if ($have[0] -ceq $made[0]) { Write-Host ("  FRESH   {0}  ({1} chars)" -f $rel, $have[0].Length) }
    else { Write-Host ("  STALE   {0}  (depot {1} chars, regenerated {2}); regenerate with codex/plugs/ptx/run.ps1 -Chapter" -f $rel, $have[0].Length, $made[0].Length); $stale++ }
}
Write-Host "ptx-fresh: $($chapters.Count) chapter(s), $($chapters.Count - $stale - $broken) fresh, $stale stale, $broken could not be checked"
if ($broken -eq 0) { Remove-Item -Recurse -Force $Work -ErrorAction SilentlyContinue }
if ($broken -gt 0) { exit 2 }
if ($stale -gt 0) { exit 1 }
exit 0
